import React, { useEffect, useState } from 'react';
import { Link } from 'react-router-dom';
import { getInspectionList } from '../../services/technicianService';
import toast from 'react-hot-toast';

const TechnicianDashboard = () => {
  const [listings, setListings] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const fetch = async () => {
      try {
        const data = await getInspectionList();
        setListings(data);
      } catch (err) {
        toast.error('Không thể tải danh sách xe cần kiểm tra');
      } finally {
        setLoading(false);
      }
    };
    fetch();
  }, []);

  if (loading) return <div className="text-center p-8">Đang tải...</div>;

  return (
    <div className="container mx-auto p-6">
      <h2 className="text-2xl font-bold mb-6">Danh sách xe cần kiểm tra kỹ thuật</h2>
      {listings.length === 0 ? (
        <div className="bg-yellow-50 p-6 rounded text-center">
          <p className="text-yellow-800">Hiện không có xe nào cần kiểm tra.</p>
        </div>
      ) : (
        <div className="grid gap-4 md:grid-cols-2 lg:grid-cols-3">
          {listings.map((car) => (
            <div key={car._id} className="border rounded-lg p-4 shadow-sm hover:shadow-md">
              <h3 className="text-xl font-semibold">{car.brand} {car.model}</h3>
              <p className="text-gray-600">{car.year} - {car.mileage.toLocaleString()} km</p>
              <p className="text-sm text-gray-500">Khách hàng: {car.customer.name}</p>
              <div className="mt-3 flex justify-between items-center">
                <span className={`px-2 py-1 rounded text-xs ${car.status === 'pending' ? 'bg-yellow-100' : 'bg-blue-100'}`}>
                  {car.status === 'pending' ? 'Chờ định giá' : 'Đã định giá'}
                </span>
                <Link
                  to={`/technician/inspect/${car._id}`}
                  className="bg-blue-600 text-white px-3 py-1 rounded hover:bg-blue-700 text-sm"
                >
                  Kiểm tra
                </Link>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
};

export default TechnicianDashboard;
